/**
 * Query defines the alias query service.
 *
 * There is deliberately no list endpoint. A typable identifier space is
 * enumerable in principle — eight characters is 2^40, which is hours of GPU
 * time — and no storage trick changes that. What the module can do is refuse to
 * hand out the directory as a convenience: walking it should cost an indexer's
 * effort, not one paginated request.
 *
 * The constraint that actually limits the damage is elsewhere: an identifier
 * maps to an address and to nothing else. No name, no telephone number, no
 * document number lives in this module, so somebody who does enumerate it
 * learns which addresses have identifiers — visible on a public chain
 * already — and nothing about who owns them.
 */
export interface Query {
  /** Params returns the module parameters. */
  Params(request: QueryParamsRequest): Promise<QueryParamsResponse>;
  /** Alias resolves an identifier to an address. The hot path. */
  Alias(request: QueryAliasRequest): Promise<QueryAliasResponse>;
  /**
   * AliasOf returns the identifier held by an address, for interfaces that
   * need to show a person their own handle.
   */
  AliasOf(request: QueryAliasOfRequest): Promise<QueryAliasOfResponse>;
  /**
   * Retired reports whether an identifier has been tombstoned. A client that
   * resolves nothing should be able to tell "never existed" from "existed and
   * was retired", because those mean very different things to somebody about
   * to send money.
   */
  Retired(request: QueryRetiredRequest): Promise<QueryRetiredResponse>;
  /** Jurisdiction reports the country recorded against one account. */
  Jurisdiction(request: QueryJurisdictionRequest): Promise<QueryJurisdictionResponse>;
  /**
   * Perimeter lists the accounts recorded in one country, so an authority can
   * see the accounts it may act on and no others.
   *
   * This is a list endpoint in a module that deliberately has none, so note
   * what it returns and what it does not: jurisdiction records, never
   * identifiers. Walking it tells you which addresses are recorded in a
   * country — a supervisory fact, and the reason the endpoint exists — and
   * gives no shortcut to the alias directory that is withheld above.
   */
  Perimeter(request: QueryPerimeterRequest): Promise<QueryPerimeterResponse>;
  /**
   * ViewingKeys returns every version of one account's viewing key, newest
   * first.
   *
   * Every version, not just the live one, because a payload encrypted last year
   * is wrapped to the key that was live last year. A client that could only
   * fetch the current key would report an old but perfectly readable payment as
   * undecryptable, which is the failure the version field exists to prevent.
   */
  ViewingKeys(request: QueryViewingKeysRequest): Promise<QueryViewingKeysResponse>;
  /**
   * Regulator returns the authority appointed over one country, with its
   * current viewing key.
   *
   * Both in one response because the sender needs both and asking separately
   * invites the half-answer: an appointment resolved, a key not fetched, and an
   * envelope built without the regulator on it that looks complete.
   */
  Regulator(request: QueryRegulatorRequest): Promise<QueryRegulatorResponse>;
  /**
   * Auditors lists the grants that have not expired, with their current keys.
   *
   * A list endpoint in a module that avoids them, and it is the right call
   * here: who may read across accounts is a fact the people being read about
   * are entitled to see, and a sender cannot build a correct envelope without
   * the whole set.
   */
  Auditors(request: QueryAuditorsRequest): Promise<QueryAuditorsResponse>;
}

